**** Gardiner pentode fitted in ValveWorkbench
**** Subcircuit generated from fitted Gardiner parameters.
**** Node order: P=plate, G2=screen, G1=control grid, K=cathode, H=heater (unused).

.subckt AS_6P6S_AS P G2 G1 K H
+ + MU=9.87039319556 KG1=0.789013827777 KP=47.1936657449 KVB=1568.40561286 KVB1=26.9556974024 VCT=1.39914153459 X=1.48882377511
+ + KG2=38.2151202041 KG2A=52926.0111155 A=0.0142650328451 ALPHA=-0.00196511609028 BETA=0.00679255109057 GAMMA=0.156292586461 OS=0
+ + TAU=0 RHO=0.00598271270225 THETA=0.856294253653 PSI=10957.7022213 OMEGA=24.8417868917 LAMBDA=0 NU=0.795980450291 S=-5.77448552406e-05 AP=0.0284812318448

* Helper functions for Cohen–Helie Epk, reused by Gardiner.
.func CH_f(v)    { sqrt( max( 0, KVB + KVB1*v + v*v ) ) }
.func CH_y(v,vg) { KP * ( 1/MU + (vg + VCT)/(CH_f(v) + 1e-9) ) }
.func CH_ep(v,vg){ v/KP * ln( 1 + exp( limit(CH_y(v,vg), -50, 50) ) ) }

* For Gardiner, epk is driven by screen voltage (normalised) and grid1 bias.
.func G_v2norm(v2){ if( abs(v2) < 5, v2*1000, v2 ) }
.func G_epk(v2,vg1){ max( CH_ep( G_v2norm(v2), vg1 ), 1e-6 ) }

* Derived helpers matching GardinerPentode::anodeCurrent/screenCurrent.
.func G_k()           { 1/max(KG1,1e-9) - 1/max(KG2,1e-9) }
.func G_scale(va,vg1) { 1 - exp( - (abs(BETA*(1-ALPHA*vg1)*va)+1e-12)**GAMMA ) }
.func G_vco(v2,vg1)   { v2/LAMBDA - vg1*NU - OMEGA }
.func G_psec(va,v2,vg1){ va*S * ( 1 + tanh( -AP*(va - G_vco(v2,vg1)) ) ) }
.func G_termIa(va,vg1){ G_k()*G_scale(va,vg1) + A*va/max(KG2,1e-9) }
.func G_sh2(vg1)      { RHO*(1-TAU*vg1) }
.func G_h(va,vg1)     { exp( - (abs(G_sh2(vg1)*va)+1e-12)**(THETA*0.9) ) }
.func G_termIg2(va,vg1){ (1 + PSI*G_h(va,vg1))/max(KG2A,1e-9) - A*va/max(KG2A,1e-9) }

.func G_ia(va,vg1,v2)  { G_epk(v2,vg1)*G_termIa(va,vg1) + OS*v2 }

.func G_ig2(va,vg1,v2) { G_epk(v2,vg1)*G_termIg2(va,vg1) }

* Behavioural current sources: anode (P→K) and screen (G2→K).
Biak  P  K  I = { max( G_ia(  V(P,K), V(G1,K), V(G2,K) ), 0 ) }
Big2  G2 K  I = { max( G_ig2( V(P,K), V(G1,K), V(G2,K) ), 0 ) }

.ends AS_6P6S_AS
